import { expect, type Page } from "@playwright/test";

/** The datagrid's row and header height (`cellHeight`, src/components/Datagrid/styles.ts). */
const GRID_ROW_HEIGHT = 40;

/**
 * A promotion, from finding it on the promotions list to managing its rules. No page object
 * covered the promotion screens before; the locators are the dashboard's `data-test-id`s, apart
 * from the rules empty state, which has none.
 */
export class PromotionPage {
  readonly searchInput = this.page.getByTestId("search-input");

  readonly list = this.page.getByTestId("list");

  readonly emptyListText = this.page.getByTestId("empty-data-grid-text");

  readonly rowAnchor = this.page.getByTestId("datagrid-row-anchor");

  readonly header = this.page.getByTestId("page-header");

  readonly nameInput = this.page.getByTestId("discount-name-input");

  readonly typeInfo = this.page.getByTestId("promotion-type-info");

  readonly rulesSection = this.page.getByTestId("discount-rules-section");

  readonly ruleList = this.page.getByTestId("rule-list");

  readonly rules = this.ruleList.getByTestId("added-rule");

  readonly rulesEmptyState = this.ruleList.getByText("Add your first rule to set up a promotion");

  readonly deleteRuleDialog = this.page.getByTestId("delete-rule-dialog");

  readonly confirmDeleteRuleButton = this.deleteRuleDialog.getByTestId("delete-rule-button");

  constructor(readonly page: Page) {}

  /**
   * Searches with the full name, because the promotions search matches nothing on a partial
   * one, and opens the single result.
   *
   * The list is a canvas datagrid: its rows are not clickable elements. The grid mirrors them
   * in a table inside the canvas, which is never rendered, so it is only read (hidden rows
   * included) to know the search has settled on that one promotion. The row is then hovered
   * by position, which places the grid's row link over it, and the link is clicked.
   */
  async open(name: string) {
    await this.page.goto("/discounts/sales");
    await this.searchInput.fill(name);
    await this.page.waitForURL(url => url.searchParams.get("query") === name);
    await expect(this.emptyListText).toBeHidden();
    // The header row plus the one result.
    await expect(this.list.getByRole("row", { includeHidden: true })).toHaveCount(2);
    await expect(
      this.list.getByRole("gridcell", { name, exact: true, includeHidden: true }),
    ).toHaveCount(1);

    const box = await this.list.boundingBox();

    if (!box) throw new Error("The promotions list is not on screen");

    await this.list.hover({ position: { x: box.width / 2, y: GRID_ROW_HEIGHT * 1.5 } });
    await this.rowAnchor.click();
    await this.page.waitForURL(url => /^\/discounts\/sales\/[^/]+$/.test(url.pathname));
    await this.waitForLoaded();
  }

  async waitForLoaded() {
    await this.ruleList.waitFor();
  }

  /** Takes effect on confirming; the promotion does not need saving. */
  async deleteRule() {
    await this.rules.getByTestId("rule-delete-button").click();
    await expect(this.deleteRuleDialog).toContainText("Delete rule");
    await this.confirmDeleteRuleButton.click();
    await this.deleteRuleDialog.waitFor({ state: "hidden" });
  }
}

import { type Page } from "@playwright/test";

import { expect, test } from "../../fixtures/test.ts";
import { ORDERS_SCENARIO, PROMOTIONS } from "../../scenarios/orders.ts";

/**
 * Staff removing a rule from a promotion (ticket 08): marketing ends an offer for part of the
 * catalogue while the promotion carries on. There was no e2e coverage of promotions, and the
 * point is that the promotion survives losing its last rule, and that the removal persists.
 *
 * The orders scenario's catalogue promotion has exactly one rule, so removing it must leave
 * the same promotion with none.
 */

/** The datagrid's row and header height (`cellHeight`, src/components/Datagrid/styles.ts). */
const GRID_ROW_HEIGHT = 40;

/**
 * Belongs in e2e/pages/promotionPage.ts; it lives here only because the generator could write
 * nothing outside e2e/tests. No page object covered the promotion screens before.
 */
class PromotionPage {
  readonly searchInput = this.page.getByTestId("search-input");

  readonly list = this.page.getByTestId("list");

  readonly emptyListText = this.page.getByTestId("empty-data-grid-text");

  readonly rowAnchor = this.page.getByTestId("datagrid-row-anchor");

  readonly header = this.page.getByTestId("page-header");

  readonly nameInput = this.page.getByTestId("discount-name-input");

  readonly typeInfo = this.page.getByTestId("promotion-type-info");

  readonly ruleList = this.page.getByTestId("rule-list");

  readonly rules = this.ruleList.getByTestId("added-rule");

  // The empty state has no test id.
  readonly rulesEmptyState = this.ruleList.getByText("Add your first rule to set up a promotion");

  readonly deleteRuleDialog = this.page.getByTestId("delete-rule-dialog");

  readonly confirmDeleteRuleButton = this.deleteRuleDialog.getByTestId("delete-rule-button");

  constructor(readonly page: Page) {}

  /**
   * Searches with the full name, because the promotions search matches nothing on a partial
   * one, and opens the single result.
   *
   * The list is a canvas datagrid: its rows are not clickable elements. The grid mirrors them
   * in a table inside the canvas, which is never rendered, so it is only read (hidden rows
   * included) to know the search has settled on that one promotion. The first row is then
   * hovered by position, which places the grid's row link over it, and the link is clicked.
   */
  async open(name: string) {
    await this.page.goto("/discounts/sales");
    await this.searchInput.fill(name);
    await this.page.waitForURL(url => url.searchParams.get("query") === name);
    await expect(this.emptyListText).toBeHidden();
    // The header row plus the one result.
    await expect(this.list.getByRole("row", { includeHidden: true })).toHaveCount(2);
    await expect(
      this.list.getByRole("gridcell", { name, exact: true, includeHidden: true }),
    ).toHaveCount(1);

    const box = await this.list.boundingBox();

    if (!box) throw new Error("The promotions list is not on screen");

    await this.list.hover({ position: { x: box.width / 2, y: GRID_ROW_HEIGHT * 1.5 } });
    await this.rowAnchor.click();
    await this.page.waitForURL(url => /^\/discounts\/sales\/[^/]+$/.test(url.pathname));
    await this.waitForLoaded();
  }

  async waitForLoaded() {
    await this.ruleList.waitFor();
  }

  /** Takes effect on confirming; the promotion does not need saving. */
  async deleteRule() {
    await this.rules.getByTestId("rule-delete-button").click();
    await expect(this.deleteRuleDialog).toContainText("Delete rule");
    await this.confirmDeleteRuleButton.click();
    await this.deleteRuleDialog.waitFor({ state: "hidden" });
  }
}

test.use({ scenario: ORDERS_SCENARIO });

test.describe("Promotion rule removal", () => {
  test("staff can remove the only rule from a catalogue promotion and the promotion remains #e2e", async ({
    page,
  }) => {
    // Arrange
    const promotion = new PromotionPage(page);
    const { name, percent } = PROMOTIONS.catalogue;
    let promotionUrl = "";

    await test.step("open the E2E Tee sale promotion", async () => {
      await promotion.open(name);
      // Kept to prove later that the page never left the promotion; the id is never typed.
      promotionUrl = page.url();
      await expect(promotion.nameInput).toHaveValue(name);
      await expect(promotion.typeInfo).toHaveText("Catalog");
      // The story is about removing the only rule, so it must start with exactly the seeded one.
      await expect(promotion.rules).toHaveCount(1);
      await expect(promotion.rules.getByTestId("rule-value-chip")).toHaveText(`${percent}%`);
    });

    // Act & Assert
    await test.step("delete the rule and confirm", () => promotion.deleteRule());

    await test.step("the promotion shows no rules", async () => {
      await expect(promotion.rules).toHaveCount(0);
      await expect(promotion.rulesEmptyState).toBeVisible();
      await expect(promotion.nameInput).toHaveValue(name);
      // A redirect to the list would mean the whole promotion was deleted.
      await expect(page).toHaveURL(promotionUrl);
    });

    await test.step("after a reload the promotion still exists with no rules", async () => {
      await page.reload();
      await promotion.waitForLoaded();
      await expect(promotion.nameInput).toHaveValue(name);
      await expect(promotion.header).toContainText(name);
      await expect(promotion.rules).toHaveCount(0);
      await expect(promotion.rulesEmptyState).toBeVisible();
    });
  });
});

