3	import { ORDERS_SCENARIO, PROMOTIONS } from "../../scenarios/orders.ts";
4	
5	/**
6	 * Staff removing a rule from a promotion (ticket 08): marketing ends an offer for part of the
7	 * catalogue while the promotion carries on. There was no e2e coverage of promotions, and the
8	 * point is that the promotion survives losing its last rule, and that the removal persists.
9	 *
10	 * The orders scenario's catalogue promotion has exactly one rule, so removing it must leave
11	 * the same promotion with none.
12	 */
13	
14	test.use({ scenario: ORDERS_SCENARIO });
15	
16	test.describe("Promotion rule removal", () => {
17	  test("staff can remove the only rule from a catalogue promotion and the promotion remains #e2e", async ({
18	    page,
19	  }) => {
20	    // Arrange
21	    const promotion = new PromotionPage(page);
22	    const { name, percent } = PROMOTIONS.catalogue;
23	    let promotionUrl = "";
24	
25	    await test.step("open the E2E Tee sale promotion", async () => {
26	      await promotion.open(name);
27	      // Kept to prove later that the page never left the promotion; the id is never typed.
28	      promotionUrl = page.url();
29	      await expect(promotion.nameInput).toHaveValue(name);
30	      await expect(promotion.typeInfo).toHaveText("Catalog");
31	      // The story is about removing the only rule, so it must start with exactly the seeded one.
32	      await expect(promotion.rules).toHaveCount(1);
33	      await expect(promotion.rules.getByTestId("rule-value-chip")).toHaveText(`${percent}%`);
34	    });
35	
36	    // Act & Assert
